    "content": "name: Build Android APK with Buildozer\n\non:\n  push:\n    branches: [ \"main\", \"master\" ]\n  pull_request:\n    branches: [ \"main\", \"master\" ]\n  workflow_dispatch:\n\njobs:\n  build:\n    name: Buildozer Android APK\n    runs-on: ubuntu-22.04\n    timeout-minutes: 60\n\n    steps:\n      - name: Checkout Repository\n        uses: actions/checkout@v4\n\n      - name: Set up Python 3.11\n        uses: actions/setup-python@v5\n        with:\n          python-version: \"3.11\"\n          cache: \"pip\"\n\n      - name: Set up Java JDK 17\n        uses: actions/setup-java@v4\n        with:\n          distribution: \"temurin\"\n          java-version: \"17\"\n\n      - name: Install System Build Dependencies\n        run: |\n          sudo apt-get update\n          sudo apt-get install -y --no-install-recommends \\\n            git \\\n            zip \\\n            unzip \\\n            autoconf \\\n            automake \\\n            libtool \\\n            pkg-config \\\n            zlib1g-dev \\\n            libncurses5-dev \\\n            libncursesw5-dev \\\n            libtinfo5 \\\n            cmake \\\n            libffi-dev \\\n            libssl-dev \\\n            build-essential \\\n            ccache \\\n            libsdl2-dev \\\n            libsdl2-image-dev \\\n            libsdl2-mixer-dev \\\n            libsdl2-ttf-dev \\\n            libportmidi-dev \\\n            libswscale-dev \\\n            libavformat-dev \\\n            libavcodec-dev\n\n      - name: Install Python Packaging Dependencies\n        run: |\n          python -m pip install --upgrade pip setuptools wheel\n          pip install --upgrade buildozer cython==0.29.36 virtualenv\n\n      - name: Verify Environment and Config\n        run: |\n          python --version\n          buildozer --version\n          test -f buildozer.spec || (echo \"buildozer.spec missing!\" && exit 1)\n\n      - name: Build Android Debug APK\n        run: |\n          # Run buildozer in debug mode\n          buildozer android debug\n\n      - name: Locate and Stage APK\n        id: stage_apk\n        run: |\n          mkdir -p output_apk\n          find bin/ -name \"*.apk\" -exec cp {} output_apk/ \\;\n          echo \"Found APK files:\"\n          ls -la output_apk/\n\n      - name: Upload Debug APK Artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: DungeonRaycast3D-Android-Debug-APK\n          path: output_apk/*.apk\n          retention-days: 14\n          if-no-files-found: error\n"
